CSS2=""".ticker{background:var(--ink);overflow:hidden;white-space:nowrap;border-bottom:3px solid var(--ink)}.tk{display:inline-block;padding:6px 0;animation:tk 180s linear infinite}.tk a{color:var(--yel);text-decoration:none;font-weight:800;margin:0 18px;font-size:.85rem}.ticker:hover .tk{animation-play-state:paused}@keyframes tk{from{transform:translateX(0)}to{transform:translateX(-50%)}}@media (prefers-reduced-motion:reduce){.tk{animation:none}.ticker{overflow-x:auto}}
.stamp{font-weight:800;font-size:.85rem;margin:0 0 8px}.nav a.hot{background:var(--pink);color:#fff}.newb{background:var(--lime);color:var(--ink);border:2px solid var(--ink);border-radius:99px;padding:0 7px;font-size:.7rem;font-weight:900;margin-left:6px}
.cdn{display:block;font-weight:900;color:var(--pink);font-size:.85rem;margin-top:4px}.hn{display:flex;gap:6px;margin-top:8px}.hn button,.share button,.opts button{font:inherit;font-weight:800;border:2px solid var(--ink);border-radius:10px;background:#fff;padding:3px 10px;cursor:pointer}.hn button.on{background:var(--yel)}.hn span{font-size:.75rem;align-self:center}
.share{margin:22px 0;display:flex;flex-wrap:wrap;gap:6px;align-items:center}.share a{border:2px solid var(--ink);border-radius:10px;padding:2px 9px;text-decoration:none;color:var(--ink);font-weight:800;background:#fff}
.quiz{background:var(--cyan);border:3px solid var(--ink);border-radius:20px;padding:16px;box-shadow:5px 5px 0 var(--ink);margin-top:20px}.quiz h2{margin-top:0}.opts{display:grid;gap:8px}.opts button.ok{background:var(--lime)}.opts button.no{background:#ffb3c7}"""
CSS=""":root{--pink:#ff2d87;--yel:#ffd60a;--cyan:#00d1ff;--lime:#7CFF4F;--ink:#16121f}*{box-sizing:border-box}body{margin:0;font-family:'Trebuchet MS',system-ui,-apple-system,sans-serif;background:#fffaf0;color:var(--ink);line-height:1.55}
a{color:#c0005a}header{position:sticky;top:0;background:var(--yel);border-bottom:3px solid var(--ink);z-index:9}.nav{max-width:1100px;margin:auto;display:flex;gap:10px;align-items:center;padding:10px 14px;overflow-x:auto;white-space:nowrap}
.logo{font-weight:900;font-size:1.3rem;text-decoration:none;color:var(--ink);letter-spacing:-.5px}.nav a.l{color:var(--ink);text-decoration:none;font-weight:700;font-size:.85rem;background:#fff;border:2px solid var(--ink);border-radius:99px;padding:3px 10px}
main{max-width:1100px;margin:auto;padding:18px 14px}.hero{background:linear-gradient(120deg,var(--pink),#ff7a00 50%,var(--yel));color:#fff;border:3px solid var(--ink);border-radius:24px;padding:26px 20px;box-shadow:6px 6px 0 var(--ink)}
.hero h1{font-size:clamp(2.1rem,8vw,4rem);line-height:1;margin:.15em 0;font-weight:900;letter-spacing:-1.5px}.hero p{font-size:1.1rem;font-weight:600;margin:.3em 0}
h2{font-size:1.6rem;font-weight:900;margin:1.4em 0 .5em}.grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(250px,1fr))}
.card{background:#fff;border:2.5px solid var(--ink);border-radius:16px;padding:14px;box-shadow:4px 4px 0 var(--ink)}.card:nth-child(4n+1){background:#fff0f6}.card:nth-child(4n+2){background:#effcff}.card:nth-child(4n+3){background:#f3ffec}
.card h3{margin:.35em 0 .25em;font-size:1.08rem;line-height:1.25}.card p{margin:.2em 0 .5em;font-size:.95rem}.pill{display:inline-block;background:var(--ink);color:var(--yel);border-radius:99px;padding:1px 9px;font-weight:800;font-size:.75rem}.cat{font-size:.75rem;font-weight:800;text-decoration:none;color:var(--ink);margin-left:6px}
.links{display:flex;flex-wrap:wrap;gap:5px}.links a{font-size:.75rem;font-weight:700;text-decoration:none;border:1.5px solid var(--ink);border-radius:8px;padding:1px 7px;color:var(--ink);background:#fff}.links a.in{background:var(--lime)}.links a.s{background:var(--yel)}
.picks .card{background:#fff !important;border-color:var(--pink);box-shadow:4px 4px 0 var(--pink)}table{width:100%;border-collapse:collapse;margin:1em 0;background:#fff}td,th{border:2px solid var(--ink);padding:8px;text-align:left;vertical-align:top}
.pnote,.fnote{font-size:.78rem;color:#555;margin:.3em 0 .6em;font-weight:400}.fnote{margin:0 0 .8em}.by{font-weight:700;color:#555;font-size:.9rem}.src{font-size:.88rem}.warn{background:#fff3b0;border:3px solid var(--ink);border-radius:14px;padding:12px;margin:12px 0;font-size:.95rem}.cats{display:flex;flex-wrap:wrap;gap:8px}.cats a{background:#fff;border:2px solid var(--ink);border-radius:99px;padding:5px 12px;text-decoration:none;color:var(--ink);font-weight:800}
footer{max-width:1100px;margin:40px auto 0;padding:20px 14px;border-top:3px solid var(--ink);font-size:.85rem}footer a{color:var(--ink);margin-right:12px;font-weight:700}"""
JS=r"""(function(){var d=document,ls=window.localStorage,now=Date.now();
function ago(ms){var m=Math.round(ms/60000);if(m<1)return"just now";if(m<60)return m+" min ago";var h=Math.round(m/60);if(h<48)return h+" hr ago";return Math.round(h/24)+" days ago"}
d.querySelectorAll("[data-updated]").forEach(function(e){e.textContent="Updated "+ago(now-Date.parse(e.dataset.updated))});
var last=0;try{last=+ls.getItem("ti_last")||0;ls.setItem("ti_last",now)}catch(e){}
d.querySelectorAll(".card[data-added]").forEach(function(c){if(last&&Date.parse(c.dataset.added)>last){var b=d.createElement("span");b.className="newb";b.textContent="NEW since your last visit";c.querySelector("h3").appendChild(b)}});
function tick(){d.querySelectorAll("[data-countdown]").forEach(function(c){var t=Date.parse(c.dataset.countdown)-Date.now(),e=c.querySelector(".cdn");if(!e){e=d.createElement("span");e.className="cdn";c.querySelector("h3").after(e)}if(t<=0){e.textContent="🎉 It's here!";return}var D=Math.floor(t/864e5),H=Math.floor(t%864e5/36e5),M=Math.floor(t%36e5/6e4);e.textContent="⏳ "+D+"d "+H+"h "+M+"m to go"})}tick();setInterval(tick,30000);
var tk=d.querySelector(".tk");if(tk)tk.innerHTML+=tk.innerHTML;
var V={};try{V=JSON.parse(ls.getItem("ti_votes")||"{}")}catch(e){}
d.querySelectorAll(".card[data-id]").forEach(function(c){var id=c.dataset.id,w=d.createElement("div");w.className="hn";w.innerHTML='<button type="button" data-v="hot">🔥 Hot</button><button type="button" data-v="not">🧊 Not</button><span></span>';c.appendChild(w);
function paint(){w.querySelectorAll("button").forEach(function(b){b.classList.toggle("on",V[id]===b.dataset.v)});w.querySelector("span").textContent=V[id]?"You said "+(V[id]==="hot"?"hot 🔥":"not 🧊"):""}paint();
w.addEventListener("click",function(e){var v=e.target.dataset&&e.target.dataset.v;if(!v)return;V[id]=V[id]===v?undefined:v;try{ls.setItem("ti_votes",JSON.stringify(V))}catch(x){}paint()})});
d.querySelectorAll(".js-share").forEach(function(b){b.hidden=false;b.addEventListener("click",function(){var u=b.dataset.url,t=b.dataset.title;if(navigator.share){navigator.share({title:t,url:u}).catch(function(){})}else if(navigator.clipboard){navigator.clipboard.writeText(u);b.textContent="Link copied ✅"}})});
var q=d.getElementById("quiz");if(q){var Q=__QUIZ__,day=Math.floor((now-new Date().getTimezoneOffset()*6e4)/864e5),n=Q.length,a=day%n,o=[a,(a*7+3)%n,(a*13+5)%n];if(o[1]===a)o[1]=(a+1)%n;if(o[2]===a||o[2]===o[1])o[2]=(a+2)%n;o.sort(function(x,y){return((x*31+day)%7)-((y*31+day)%7)});
q.hidden=false;q.querySelector(".q").textContent="Today's clue: “"+Q[a][1]+"” Which trend is it?";var box=q.querySelector(".opts"),res=q.querySelector(".res"),k="ti_quiz_"+day,done=ls.getItem(k);
o.forEach(function(i){var b=d.createElement("button");b.type="button";b.textContent=Q[i][0];b.onclick=function(){box.querySelectorAll("button").forEach(function(x){x.disabled=true});b.className=i===a?"ok":"no";res.textContent=i===a?"Nailed it 🎯 New clue tomorrow.":"Nope! It was "+Q[a][0]+". Try again tomorrow.";try{ls.setItem(k,i===a?"1":"0")}catch(e){}};box.appendChild(b)});
if(done){res.textContent="You already played today ("+(done==="1"?"you got it 🎯":"missed it")+"). Come back tomorrow!"}}
})();"""
